urlset:
{%- for locale, i18n_files in i18n_alternates.items() %}
{%- for file in i18n_files %}
    {%- if not file.page or file.page.is_link %}{% continue %}{% endif %}
    {#- mkdocs-static-i18n copies untranslated pages into every locale. Those
        copies carry the default locale and must not be advertised here. #}
    {%- if file.locale != locale %}{% continue %}{% endif %}
    {%- if file.page.canonical_url %}{% set page_href = file.page.canonical_url | e %}
    {%- elif file.page.abs_url %}{% set page_href = file.page.abs_url | e %}
    {%- else %}{% set page_href = config.site_url ~ file.url %}{% endif %}

        {{ page_href }}
    {%- if file.page.update_date %}
        {{ file.page.update_date }}
    {%- endif %}
        daily
    {%- for i18n_locale, i18n_file in file.alternates.items() %}
        {#- only list a translation when the alternate really is that locale #}
        {%- if i18n_file.locale != i18n_locale %}{% continue %}{% endif %}
        {%- if i18n_file.page and i18n_file.page.canonical_url %}
            {%- set i18n_href = i18n_file.page.canonical_url | e %}
        {%- elif i18n_file.page and i18n_file.page.abs_url %}
            {%- set i18n_href = i18n_file.page.abs_url | e %}
        {%- elif i18n_file.url == "./" %}
            {%- set i18n_href = config.site_url %}
        {%- else %}
            {%- set i18n_href = config.site_url ~ i18n_file.url %}
        {%- endif %}

    {%- endfor %}

{%- endfor %}
{%- endfor %}
